pub type Move = enum {
  Up,
  Down,
  Left,
  Right,
} derive[Eq, Clone]

fn opposite(m: &Move) -> Move {
  match m {
    Up => { return Move.Down; }
    Down => { return Move.Up; }
    Left => { return Move.Right; }
    Right => { return Move.Left; }
  }
}

fn is_vertical(m: &Move) -> Bool {
  return m == &Move.Up || m == &Move.Down;
}

fn main() -> Int {
  let up = Move.Up;
  let cloned = up.clone();
  if up == cloned {
    return 1;
  }
  return 0;
}
